{
  "name": "Modbus ADU报文解码器",
  "name_en": "Modbus ADU Message Decoder",
  "manufacturer": "",
  "description": "用于解析 Modbus 应用数据单元（ADU）报文的软件工具，常用于实验室或工业通信调试中分析串口/RTU 数据流、校验 CRC，并识别写单线圈、写单寄存器、诊断等功能码消息。",
  "description_en": "A software tool for decoding Modbus Application Data Unit (ADU) messages. It is commonly used in laboratory or industrial communication troubleshooting to analyze serial/RTU traffic, verify CRC values, and identify messages such as write single coil, write single register, and diagnostics.",
  "tag_hints": [
    "Modbus RTU",
    "serial protocol decoding",
    "CRC checking",
    "industrial communication analysis",
    "UART packet parsing",
    "logic analyzer"
  ],
  "actions": [
    {
      "action_name": "auto-add_data",
      "description": "向当前 Modbus ADU 解析过程添加一段接收到的数据。",
      "description_en": "Add a received data segment to the current Modbus ADU being decoded."
    },
    {
      "action_name": "auto-puti",
      "description": "为尚未标注的指定字节写入解码注释信息。",
      "description_en": "Write a decoded annotation for a specified byte that has not yet been annotated."
    },
    {
      "action_name": "auto-putl",
      "description": "为最后一个字节写入解码注释信息。",
      "description_en": "Write a decoded annotation for the last byte."
    },
    {
      "action_name": "auto-close",
      "description": "结束当前报文解析，并处理消息结束处的溢出或错误标记。",
      "description_en": "Close the current message decoding and handle overflow or error marking at the end of the frame."
    },
    {
      "action_name": "auto-check_crc",
      "description": "检查当前 Modbus 报文的 CRC 校验值。",
      "description_en": "Check the CRC value of the current Modbus message."
    },
    {
      "action_name": "auto-half_word",
      "description": "读取并解释指定偏移处的 16 位数据。",
      "description_en": "Read and interpret a 16-bit value at the specified offset."
    },
    {
      "action_name": "auto-calc_crc",
      "description": "计算当前 Modbus 报文内容的 CRC 值。",
      "description_en": "Calculate the CRC value for the current Modbus message content."
    },
    {
      "action_name": "auto-parse_write_single_coil",
      "description": "解析 Modbus 写单个线圈功能码报文。",
      "description_en": "Parse a Modbus write single coil function message."
    },
    {
      "action_name": "auto-parse_write_single_register",
      "description": "解析 Modbus 写单个寄存器功能码报文。",
      "description_en": "Parse a Modbus write single register function message."
    },
    {
      "action_name": "auto-parse_diagnostics",
      "description": "解析 Modbus 诊断功能码报文。",
      "description_en": "Parse a Modbus diagnostics function message."
    },
    {
      "action_name": "auto-parse_mask_write_register",
      "description": "解析 Modbus 掩码写寄存器功能码报文。",
      "description_en": "Parse a Modbus mask write register function message."
    },
    {
      "action_name": "auto-parse_not_implemented",
      "description": "标记或处理尚未实现解析的合法 Modbus 功能码。",
      "description_en": "Mark or handle legal Modbus function codes that are not yet implemented in the parser."
    }
  ]
}

